// Generate the pinned Unicode 15.0.0 simple case maps using Go's public API.
// Classification tables are generated by gen_unicode_tables.go.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"unicode"
)

const pageSize = 256
const deltaBias = 1 << 17

type caseMap struct {
	name  string
	f     func(rune) rune
	index string
}

// A page index is one printable byte (0 means identity). Deltas use three
// printable six-bit bytes, biased by 2^17. Reads need no hex parsing, search,
// allocation or sign branch. Equal pages are shared across all four maps.
func pages(maps []caseMap) string {
	pool := map[string]int{}
	var data bytes.Buffer
	for mi := range maps {
		t := &maps[mi]
		var index bytes.Buffer
		last := -1
		for base := 0; base <= unicode.MaxRune; base += pageSize {
			var page bytes.Buffer
			changed := false
			for i := 0; i < pageSize; i++ {
				r := base + i
				d := int(t.f(rune(r))) - r
				changed = changed || d != 0
				v := d + deltaBias
				if v < 0 || v >= 1<<18 {
					panic("case delta exceeds packed 18-bit range")
				}
				page.WriteByte(byte(32 + ((v >> 12) & 63)))
				page.WriteByte(byte(32 + ((v >> 6) & 63)))
				page.WriteByte(byte(32 + (v & 63)))
			}
			id := 0
			if changed {
				key := page.String()
				id = pool[key]
				if id == 0 {
					id = len(pool) + 1
					if id > 94 {
						panic("case page index exceeds printable byte range")
					}
					pool[key] = id
					data.WriteString(key)
				}
				last = index.Len()
			}
			index.WriteByte(byte(32 + id))
		}
		t.index = index.String()[:last+1]
	}
	return data.String()
}

func emitLookup(out *bytes.Buffer, t caseMap) {
	fmt.Fprintf(out, "const case_%s_index = %q\n", t.name, t.index)
	fmt.Fprintf(out, `
fn case_%s(r int) int {
    page := r >> 8
    if page < 0 || page >= %d { << r }
    index := case_%s_index
    block := index[page] - 32
    if block == 0 { << r }
    data := case_page_data
    pos := (block - 1) * 768 + (r & 255) * 3
    d := ((data[pos] - 32) << 12) | ((data[pos + 1] - 32) << 6) | (data[pos + 2] - 32)
    << r + d - 131072
}
`, t.name, len(t.index), t.name)
}

func main() {
	out := flag.String("out", "src/unicode/case_tables.xu", "output file")
	check := flag.Bool("check", false, "check without writing")
	flag.Parse()
	if unicode.Version != "15.0.0" {
		fmt.Fprintln(os.Stderr, "requires Unicode 15.0.0; found", unicode.Version)
		os.Exit(1)
	}
	maps := []caseMap{
		{name: "upper", f: unicode.ToUpper},
		{name: "lower", f: unicode.ToLower},
		{name: "fold", f: unicode.SimpleFold},
		{name: "title", f: unicode.ToTitle},
	}
	data := pages(maps)
	var b bytes.Buffer
	fmt.Fprintln(&b, "@unicode\n\n// AUTO-GENERATED by scripts/gen_unicode_case_tables.go; Unicode 15.0.0.")
	fmt.Fprintln(&b, "// Source: Go unicode public mappings, derived from the Unicode Character Database.")
	fmt.Fprintln(&b, "// https://www.unicode.org/Public/15.0.0/ucd/ ; shared 256-rune pages, biased 18-bit deltas.")
	fmt.Fprintf(&b, "const case_page_data = %q\n\n", data)
	for _, t := range maps {
		emitLookup(&b, t)
	}
	if *check {
		data, err := os.ReadFile(*out)
		if err != nil || !bytes.Equal(data, b.Bytes()) {
			os.Exit(1)
		}
	} else if err := os.WriteFile(*out, b.Bytes(), 0644); err != nil {
		panic(err)
	}
}
